        "version": "schemaxis.infozip/1",
        "operation": "bundle",
        "files": [
          {
            "name": "narration.flac",
            "source": {
              "$artifact": "archive",
              "index": 0
            }
          },
          {
            "name": "narration-summary.json",
            "source": {
              "$artifact": "narration",
              "index": 1
            }
          },
          {
            "name": "archive-summary.json",
